  "Cornerstone":
    "이탈리아 인디 라벨. 컨템포러리 멘즈웨어.",

  "PDF": "이탈리아 디자이너 도메니코 포르미차리(Domenico Formichetti)의 우니섹스 라벨 'PDF Channel'. 시그니처는 90s·Y2K 영감의 컨템포러리 우니섹스웨어.\n\n시그니처는 컬러풀·박시한 컨템포러리 우니섹스웨어 — 시그니처 그래픽 자켓·후디, 와이드 카고 트라우저, 컬러풀 미니드레스가 라인업의 중심이다. '90s revival'과 사이버펑크 미학의 결합.\n\nSSENSE, MATCHESFASHION, Dover Street Market 등 글로벌 컨템포러리 럭셔리 채널에서 전개. 이탈리아 신진 우니섹스 디자이너의 대표 격으로 자리잡았다.",

  "Parel Studios": "2017년 네덜란드 암스테르담에서 설립된 우먼즈웨어 라벨. 본업은 미니멀 컨템포러리 RTW.\n\n시그니처는 미니멀·정제된 컨템포러리 우먼즈웨어 — 부드러운 울·코튼 원단의 박시한 자켓, 와이드 트라우저, 미니멀 셔츠·드레스가 라인업의 중심이다. 컬러 팔레트는 뉴트럴 베이지·아이보리·블랙 등 모노톤 중심.\n\nSSENSE, MATCHESFASHION, MyTheresa 등 글로벌 컨템포러리 럭셔리 채널에서 전개. 네덜란드 신진 미니멀 우먼즈웨어 신의 신생 디자이너 결로 자리잡았다.",

