  "Seventh":
    "한국 인디 라벨. 컨템포러리 우니섹스.",

  "Silas": "1996년 영국에서 설립된 일본·영국계 스케이트보드 라벨. 90s·00s 영국 스트릿웨어의 정통파.\n\n시그니처는 90s 영국 스케이트·청년 컬쳐 헤리티지의 그래픽 후디·티, 빈티지 영감의 자켓·트라우저가 라인업의 중심이다. 'Silas' 로고 그래픽과 시그니처 90s 컬러웨이.\n\n일본·영국·미국 스케이트 컬쳐 셀렉트샵에서 전개. 90s 영국 스케이트웨어의 정통 헤리티지 브랜드 중 하나로, 동시대 Stüssy·Supreme 등과 함께 90s 청년 컬쳐 스트릿웨어 신의 핵심 멤버였다.",

  "Situationist": "조지아 디자이너 이라클리 루사드제(Irakli Rusadze)가 트빌리시에서 설립한 우니섹스 라벨.\n\n시그니처는 80s·90s 영감의 데미지·해체된 우니섹스 컨템포러리 RTW — 오버사이즈 자켓·코트, 와이드 트라우저, 시그니처 데컨스트럭티드 셔츠가 라인업의 중심이다. 'Soviet aesthetic'·동유럽 헤리티지의 컨템포러리 재해석.\n\n파리 패션위크 정식 멤버이며, 도버 스트리트 마켓, SSENSE, MATCHESFASHION 등 글로벌 럭셔리 셀렉트샵에서 전개. Materiel Tbilisi, Anna October 등과 함께 조지아·동유럽 디자이너 신의 정통 결로 자리잡았다.",

