  "SPENCER BADU": "2017년 캐나다 디자이너 스펜서 바두(Spencer Badu)가 토론토에서 설립한 우니섹스 라벨.\n\n시그니처는 70s 가나·아프리카 헤리티지·디아스포라 정체성의 컨템포러리 우니섹스웨어 — 컬러풀 자카드 니트, 정교한 자수·텍스타일 디테일의 자켓·트라우저, 시그니처 아프리칸 패턴의 셔츠·미니드레스가 라인업의 중심이다.\n\nSSENSE, Dover Street Market, MATCHESFASHION 등 글로벌 컨템포러리 럭셔리 채널에서 전개. 토론토 단독 매장 운영. 캐나다 흑인·아프리칸 디아스포라 디자이너 신의 대표 격으로 자리잡았다.",

