  "MATIÈRES FÉCALES": "캐나다 듀오 한나 로즈 달튼(Hannah Rose Dalton)과 스티븐 라이 라플람(Steven Raj Bhaskaran)이 설립한 아방가르드 라벨.\n\n시그니처는 사이버펑크·고스·SF 미학의 아방가르드 RTW — 시그니처 메탈·라텍스 디테일의 자켓, 시어한 메시 미니드레스, 시그니처 디지털 그래픽이 라인업의 중심이다. 'Cyber goth'의 정통 결.\n\n도버 스트리트 마켓, SSENSE 등 글로벌 컨템포러리 럭셔리 채널에서 전개. 그라임스(Grimes)·아리아나 그란데 등 셀럽 단골. 캐나다·미국 신진 아방가르드 디자이너 듀오의 대표 격.",

