  "Trunk Project": "2014년 한국 디자이너 양지선(Yang Jiseon)이 서울에서 설립한 우먼즈웨어 라벨. 본업은 페미닌·플레이풀 컨템포러리 RTW.\n\n시그니처는 페미닌·플레이풀 컨템포러리 우먼즈웨어 — 컬러풀 미니드레스, 시그니처 자수·러플 디테일의 블라우스·스커트, 컬러풀 자켓이 라인업의 중심이다. 'K-feminine' 무드의 정통 결.\n\n한국 자체 사이트와 무신사·29CM 등 셀렉트샵에서 전개. K-pop 셀럽·인플루언서 단골 라벨로 한국 영 우먼즈 마켓에서 강한 입지. 2010년대 한국 컨템포러리 우먼즈웨어 신의 정통 디자이너 결.",

