  "Safsafu": "2017년 레바논·미국 디자이너 듀오 마운자 사프와(Mounza Safwa)와 자매가 NYC에서 설립한 럭셔리 주얼리·RTW. 본업은 중동 헤리티지의 컨템포러리 럭셔리.\n\n시그니처는 중동·아랍 헤리티지의 컨템포러리 럭셔리 주얼리 — 컬러풀 비드, 골드 베르메, 시그니처 아랍 캘리그래피 디테일의 주얼리·미니드레스가 라인업의 중심이다. '아랍 럭셔리 글래머'의 정통 결.\n\nNet-a-Porter, MATCHESFASHION, MyTheresa, Browns 등 글로벌 럭셔리 채널에서 전개. 두아 리파·벨라 하디드 등 셀럽 단골. NYC 아랍·중동 디아스포라 디자이너 신의 대표 격.",

